
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_lta_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_lta", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.458140424472535e+00, -1.474201833298558e+00, -1.497539326538097e+00, -1.531643360678282e+00, -1.581944353972838e+00, -1.657245208926056e+00, -1.772595603897442e+00, -1.955143455236729e+00, -2.254057047159366e+00, -2.728125802338043e+00, -3.055483351852157e+00, -1.627038369764830e+00, -4.984643336616322e-01, -4.202480167267571e-01, -5.132337402153727e-01, -6.743001408869070e-01, -9.911259595248336e-01, -1.736299235166914e+00, -4.001319619980338e+00, -1.390023517996198e+01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


